251	    @Override
252	    @Transactional
253	    public void saveOwner(Owner owner) throws DataAccessException {
254	        boolean isNew = owner.isNew();
255	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
256	        // roll it forward to the next business day so it never lands on a weekend. Everything
257	        // derived from the registration date below must use this adjusted value.
258	        LocalDate registrationDate = toBusinessDay(
259	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
260	        owner.setRegistrationDate(registrationDate);
261	        if (owner.isNew()) {
262	            // Resolve the household first so the owner's householdId is part of its identityKey. The
263	            // members are existing owners with the same last name and address; joining them makes this
264	            // owner share their stable householdId (back-filled onto any member still missing it).
265	            List<Owner> householdMembers = findHouseholdMembers(owner);
266	            if (!householdMembers.isEmpty()) {
267	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
268	            }
269	            // Size of the household after this create: the existing members plus this new owner.
270	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
271	        }
272	        // Single consolidated duplicate check: reject only when the new owner's WHOLE identityKey
273	        // (normalizedTelephone | email-or-empty | householdId) equals an existing owner's. This
274	        // subsumes the former separate telephone, email and household checks.
275	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
276	            throw new DuplicateIdentityException(owner.getIdentityKey());
277	        }
278	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's last name and
279	        // postcode while carrying a different telephone. Still created, but flagged as a possible
280	        // duplicate pointing at the matching owner.
281	        if (owner.isNew()) {
282	            Owner softMatch = findPossibleDuplicate(owner);
283	            if (softMatch != null) {
284	                owner.setPossibleDuplicate(true);
285	                owner.setPossibleDuplicateOf(softMatch.getId());
286	            }
287	        }
288	        if (owner.isNew()
289	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
290	            throw new CityOwnerLimitExceededException(owner.getCity());
291	        }
292	        if (owner.isNew()
293	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
294	            throw new DailyOwnerLimitExceededException(registrationDate);
295	        }
296	        if (owner.isNew() && owner.getCustomerCode() == null) {
297	            owner.setCustomerCode(generateCustomerCode(owner));
298	        }
299	        if (owner.isNew()) {
300	            owner.setNamesakeCount(countNamesakes(owner));
301	            owner.setBulkSignupWarning(
302	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
303	        }
304	        if (owner.getMembershipNumber() == null) {
305	            owner.setMembershipNumber(generateMembershipNumber(owner));
306	        }
307	        ownerRepository.save(owner);
308	        if (isNew) {
309	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} registrationDate={}",
310	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
311	                owner.getRegistrationDate());
312	        }
313	    }
314	
315	    /**
316	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
317	     * owner. The key consolidates telephone, email and household into one value, so two owners
318	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
319	     * the owner's {@code householdId} has been resolved, so its key is complete.
320	     */
321	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
322	        String identityKey = owner.getIdentityKey();
323	        return ownerRepository.findAll().stream()
324	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
325	    }
326	
327	    /**
328	     * Find an existing owner this (new) owner soft-matches against: one sharing the same last name
329	     * (compared case-insensitively with collapsed whitespace, like household matching) and the same
330	     * postcode, but carrying a different telephone. Returns the lowest-id such owner, or {@code null}
331	     * when the owner has no last name or postcode to match on, or nothing matches. The caller only
332	     * invokes this once the hard {@code identityKey} duplicate check has already passed.
333	     */
334	    private Owner findPossibleDuplicate(Owner owner) {
335	        String lastName = normalizeHouseholdKey(owner.getLastName());
336	        String postcode = owner.getPostcode();
337	        if (lastName == null || postcode == null || postcode.isBlank()) {
338	            return null;
339	        }
340	        String telephone = owner.getTelephone();
341	        return ownerRepository.findAll().stream()
342	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
343	                && postcode.equals(existing.getPostcode())
344	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
345	            .min(java.util.Comparator.comparing(Owner::getId))
346	            .orElse(null);
347	    }
348	
349	    /**
350	     * Count the owners that already exist (before this create) sharing the same first name and last
351	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
352	     * unique among the existing owners.
353	     */
354	    private int countNamesakes(Owner owner) {
355	        String firstName = owner.getFirstName();
356	        String lastName = owner.getLastName();
357	        if (firstName == null || lastName == null) {
358	            return 0;
359	        }
360	        return (int) ownerRepository.findAll().stream()
361	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
362	                && lastName.equalsIgnoreCase(existing.getLastName()))
363	            .count();
364	    }
365	
366	    /**
367	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
368	     * last name and the same address. Last names are compared case-insensitively with collapsed
369	     * whitespace; addresses are compared in their canonical normalized form (see
370	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
371	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
372	     * match on.
373	     */
374	    private List<Owner> findHouseholdMembers(Owner owner) {
375	        String lastName = normalizeHouseholdKey(owner.getLastName());
376	        String address = AddressNormalizer.normalize(owner.getAddress());
377	        if (lastName == null || address == null) {
378	            return List.of();
379	        }
380	        return ownerRepository.findAll().stream()
381	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
382	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
383	            .toList();
384	    }
385	
386	    /**
387	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
388	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
389	     * new one is generated. The resolved value is back-filled onto every member that is missing it
390	     * (or has a different one) so all members of the household share the same identifier.
391	     */
392	    private String resolveHouseholdId(List<Owner> members) {
393	        String householdId = members.stream()
394	            .map(Owner::getHouseholdId)
395	            .filter(id -> id != null && !id.isBlank())
396	            .findFirst()
397	            .orElseGet(() -> UUID.randomUUID().toString());
398	        for (Owner member : members) {
399	            if (!householdId.equals(member.getHouseholdId())) {
400	                member.setHouseholdId(householdId);
401	                ownerRepository.save(member);
402	            }
403	        }
404	        return householdId;
405	    }
406	
407	    /**
408	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
409	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
410	     */
411	    private String normalizeHouseholdKey(String value) {
412	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
413	    }
414	
415	    /**
416	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
417	     * code resolved from the owner's postcode (falling back to the owner's city, else
418	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
419	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
420	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
421	     * derived from the owner's own attributes.
422	     */
423	    private String generateCustomerCode(Owner owner) {
424	        return PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
425	    }
426	
427	    /**
428	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
429	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
430	     * with the owner's last name.
431	     */
432	    private String customerHash(Owner owner) {
433	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
434	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
435	        byte[] digest;
436	        try {
437	            digest = MessageDigest.getInstance("SHA-256")
438	                .digest((telephone + lastName).getBytes(StandardCharsets.UTF_8));
439	        } catch (NoSuchAlgorithmException e) {
440	            throw new IllegalStateException("SHA-256 is required but not available", e);
441	        }
442	        StringBuilder hex = new StringBuilder(16);
443	        for (int i = 0; i < 4; i++) {
444	            hex.append(String.format("%02X", digest[i]));
445	        }
446	        return hex.toString();
447	    }
448	
449	    /**
450	     * Count the owners that already exist (before this create) in the same city as {@code owner},
451	     * compared case-insensitively.
452	     */
453	    private long countOwnersInCity(Owner owner) {
454	        String city = owner.getCity();
455	        return ownerRepository.findAll().stream()
456	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
457	            .count();
458	    }
459	
460	    /**
461	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
462	     * on the given {@code date}. Used to enforce the per-day create cap.
463	     */
464	    private long countOwnersRegisteredOn(LocalDate date) {
465	        return ownerRepository.findAll().stream()
466	            .filter(existing -> date.equals(existing.getRegistrationDate()))
467	            .count();
468	    }
469	
470	    /**
471	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
472	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
473	     * are required to fall on a business day.
474	     */
475	    private LocalDate toBusinessDay(LocalDate date) {
476	        switch (date.getDayOfWeek()) {
477	            case SATURDAY:
478	                return date.plusDays(2);
479	            case SUNDAY:
480	                return date.plusDays(1);
481	            default:
482	                return date;
483	        }
484	    }
485	
486	    /**
487	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
488	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
489	     */
490	    private String generateMembershipNumber(Owner owner) {
491	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
492	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
493	    }
494	
