497	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
498	        return ownerRepository.findByLastName(lastName);
499	    }
500	
501	    @Override
502	    @Transactional(readOnly = true)
503	    public Collection<Visit> findVisitsByPetId(int petId) {
504	        return visitRepository.findByPetId(petId);
505	    }
506	
507	    @Override
508	    @Transactional(readOnly = true)
509	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
510	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
511	    }
512	
513	    private <T> T findEntityById(Supplier<T> supplier) {
514	        try {
515	            return supplier.get();
516	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
517	            // Just ignore not found exceptions for Jdbc/Jpa realization
518	            return null;
519	        }
520	    }
521	
